<?php
require_once __DIR__.'/../includes/bootstrap.php';require_role('Faculty');check_csrf();$u=current_user();$f=db()->prepare('SELECT id FROM faculty WHERE user_id=?');$f->execute([$u['id']]);$fid=(int)$f->fetchColumn();if($_SERVER['REQUEST_METHOD']==='POST'){$q=db()->prepare('INSERT INTO quizzes(subject_id,faculty_id,title,duration_minutes,open_at,close_at,status) VALUES(?,?,?,?,?,?,?)');$q->execute([(int)$_POST['subject_id'],$fid,trim($_POST['title']),(int)$_POST['duration'],$_POST['open_at'],$_POST['close_at'],'Published']);$qid=(int)db()->lastInsertId();$qq=db()->prepare('INSERT INTO quiz_questions(quiz_id,question,type,options_json,correct_answer,marks) VALUES(?,?,?,?,?,?)');for($i=1;$i<=5;$i++){if(trim($_POST['q'.$i]??''))$qq->execute([$qid,trim($_POST['q'.$i]),'MCQ',json_encode(['A'=>'Option A','B'=>'Option B','C'=>'Option C','D'=>'Option D']),$_POST['a'.$i]??'A',1]);}AuditService::log('CREATE','quizzes',$qid,'Quiz published');$_SESSION['flash']=['success','Quiz created with up to five questions'];redirect('quiz.php');}$subs=db()->query('SELECT id,code,name FROM subjects ORDER BY name')->fetchAll();page_top('Quiz Studio');flash();?><div class='card p-4'><form method='post' class='row g-3'><input type='hidden' name='csrf' value='<?=e(csrf_token())?>'><div class='col-md-5'><label>Subject</label><select name='subject_id' class='form-select'><?php foreach($subs as $s):?><option value='<?=e($s['id'])?>'><?=e($s['code'].' · '.$s['name'])?></option><?php endforeach;?></select></div><div class='col-md-7'><label>Quiz title</label><input name='title' class='form-control' required></div><div class='col-md-3'><label>Duration (min)</label><input name='duration' type='number' class='form-control' value='20'></div><div class='col-md-4'><label>Open</label><input name='open_at' type='datetime-local' class='form-control'></div><div class='col-md-4'><label>Close</label><input name='close_at' type='datetime-local' class='form-control'></div><?php for($i=1;$i<=5;$i++):?><div class='col-12 border-top pt-3'><label>Question <?=$i?></label><input name='q<?=$i?>' class='form-control mb-2'><select name='a<?=$i?>' class='form-select' style='max-width:200px'><option>A</option><option>B</option><option>C</option><option>D</option></select></div><?php endfor;?><button class='btn btn-primary'>Publish Quiz</button></form></div><?php page_bottom();